def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(
        r"\d+|[A-Z][1-9][0-9]?|[A-Z]+|<=|>=|<>|[()+*/,:<>=-]"
    )
    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "~": 3,
        ":": 4,
    }

    def parse(formula):
        nodes = []
        operators = []
        argument_counts = []
        expect_operand = True

        def reduce_operator():
            op = operators.pop()
            if op == "~":
                nodes.append(("neg", nodes.pop()))
            else:
                right = nodes.pop()
                left = nodes.pop()
                if op == ":":
                    nodes.append(("range", left[1], right[1]))
                else:
                    nodes.append(("binary", op, left, right))

        for match in token_pattern.finditer(formula):
            token = match.group()

            if token[0].isdigit():
                nodes.append(("number", int(token)))
                expect_operand = False
            elif token in functions:
                operators.append(token)
                expect_operand = True
            elif token[0].isalpha():
                nodes.append(("reference", token))
                expect_operand = False
            elif token == "(":
                is_call = bool(operators and operators[-1] in functions)
                argument_counts.append(1 if is_call else None)
                operators.append("(")
                expect_operand = True
            elif token == ",":
                while operators[-1] != "(":
                    reduce_operator()
                argument_counts[-1] += 1
                expect_operand = True
            elif token == ")":
                while operators[-1] != "(":
                    reduce_operator()
                operators.pop()
                count = argument_counts.pop()
                if count is not None:
                    function = operators.pop()
                    args = nodes[-count:]
                    del nodes[-count:]
                    nodes.append(("call", function, args))
                expect_operand = False
            elif token == "-" and expect_operand:
                operators.append("~")
            else:
                while (
                    operators
                    and operators[-1] in precedence
                    and precedence[operators[-1]] >= precedence[token]
                ):
                    reduce_operator()
                operators.append(token)
                expect_operand = True

        while operators:
            reduce_operator()
        return nodes[0]

    def argument_nodes(arguments):
        for argument in arguments:
            if argument[0] != "range":
                yield argument
                continue

            first, last = argument[1], argument[2]
            left, right = sorted((ord(first[0]), ord(last[0])))
            top, bottom = sorted((int(first[1:]), int(last[1:])))

            for row in range(top, bottom + 1):
                for column in range(left, right + 1):
                    name = chr(column) + str(row)
                    if name in cells:
                        yield ("reference", name)

    values = {}
    active = set()

    for root in cells:
        if root in values:
            continue

        tasks = [("cell", root)]
        value = 0

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]
                if name in values:
                    value = values[name]
                elif name not in cells:
                    value = 0
                elif name in active:
                    value = "#CYCLE!"
                else:
                    active.add(name)
                    tasks.append(("finish", name))
                    content = cells[name]
                    if content.startswith("="):
                        tasks.append(("node", parse(content[1:])))
                    else:
                        value = int(content)

            elif kind == "finish":
                name = task[1]
                values[name] = value
                active.remove(name)

            elif kind == "node":
                node = task[1]
                node_kind = node[0]

                if node_kind == "number":
                    value = node[1]
                elif node_kind == "reference":
                    tasks.append(("cell", node[1]))
                elif node_kind == "neg":
                    tasks.append(("negate",))
                    tasks.append(("node", node[1]))
                elif node_kind == "binary":
                    _, op, left, right = node
                    tasks.append(("left_done", op, right))
                    tasks.append(("node", left))
                elif node_kind == "call":
                    _, function, arguments = node
                    if function == "IF":
                        tasks.append(("choose", arguments[1], arguments[2]))
                        tasks.append(("node", arguments[0]))
                    else:
                        tasks.append((
                            "aggregate",
                            function,
                            argument_nodes(arguments),
                            None,
                        ))

            elif kind == "negate":
                if not isinstance(value, str):
                    value = -value

            elif kind == "left_done":
                if not isinstance(value, str):
                    tasks.append(("right_done", task[1], value))
                    tasks.append(("node", task[2]))

            elif kind == "right_done":
                if isinstance(value, str):
                    continue

                op, left, right = task[1], task[2], value
                if op == "+":
                    value = left + right
                elif op == "-":
                    value = left - right
                elif op == "*":
                    value = left * right
                elif op == "/":
                    if right == 0:
                        value = "#DIV/0!"
                    else:
                        quotient = abs(left) // abs(right)
                        value = -quotient if (left < 0) != (right < 0) else quotient
                elif op == "=":
                    value = left == right
                elif op == "<>":
                    value = left != right
                elif op == "<":
                    value = left < right
                elif op == "<=":
                    value = left <= right
                elif op == ">":
                    value = left > right
                elif op == ">=":
                    value = left >= right

            elif kind == "choose":
                if not isinstance(value, str):
                    tasks.append(("node", task[1] if value else task[2]))

            elif kind == "aggregate":
                _, function, iterator, accumulated = task
                node = next(iterator, None)
                if node is None:
                    value = 0 if accumulated is None else accumulated
                else:
                    tasks.append((
                        "aggregate_done", function, iterator, accumulated
                    ))
                    tasks.append(("node", node))

            elif kind == "aggregate_done":
                if isinstance(value, str):
                    continue

                _, function, iterator, accumulated = task
                if accumulated is None:
                    accumulated = value
                elif function == "SUM":
                    accumulated += value
                elif function == "MIN":
                    accumulated = min(accumulated, value)
                else:
                    accumulated = max(accumulated, value)

                tasks.append(("aggregate", function, iterator, accumulated))

    return {name: values[name] for name in cells}
